// Public privacy GETs from anonymous fixture contexts on Actions only; no consent or delivery.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {mkdir,mkdtemp,readFile,writeFile,symlink} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {staticOrigin} from './static-origin.mjs';
import {inventory} from '../../scripts/build-pages-artifact.mjs';
assert.equal(process.env.GITHUB_ACTIONS,'true','Use only the authorized Actions runner');
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_PACKAGE);
const artifact=resolve(process.env.PAGES_ARTIFACT),reportDir=resolve(process.env.BROWSER_REPORT);await mkdir(reportDir,{recursive:true});
const git=(...a)=>execFileSync('git',a),sha=b=>createHash('sha256').update(b).digest('hex'),publishedMain='4ab89f3b95350cf8a76ee0aeb7164ea67d16a537';
const report={head:process.env.TESTED_HEAD,base:process.env.TESTED_BASE,publishedMain,checkout:git('rev-parse','HEAD').toString().trim(),files:{},rows:[],captures:[],blocked:[],navigation:[],limits:['Live public privacy page with non-GET/HEAD and unrelated hosts blocked; no external form/account/cookie-consent interaction.','Chromium320/1280; not physical-device/native-speaker/legal or unfiltered third-party-page certification.','Shared English external destination, not20translated policy pages.']};
assert.equal(report.checkout,report.head);assert.equal(git('rev-parse','HEAD^').toString().trim(),report.base);
for(const {path:p}of inventory(artifact)){const source=p.startsWith('tools/coordinator/')?'coordinator-demo/'+p.split('/').at(-1):p,b=await readFile(join(artifact,p));assert.deepEqual(b,git('show',`${report.head}:${source}`));assert.deepEqual(b,git('show',`${publishedMain}:${source}`));report.files[p]={source,bytes:b.length,sha256:sha(b),publishedExact:true};}assert.equal(Object.keys(report.files).length,317);
const serveRoot=await mkdtemp(join(tmpdir(),'primserv-privacy-'));await symlink(artifact,join(serveRoot,'kiris-jobs'),'dir');const origin=staticOrigin(serveRoot),base='http://127.0.0.1:4173/kiris-jobs/',privacy='https://pposiechnice.pl/?lang=en&page_id=981';let browser;
const assets=new Set(['cdn.jsdelivr.net','kit.fontawesome.com','use.fontawesome.com','use.typekit.net']);
async function run(width,entry){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block',reducedMotion:'reduce'});ctx.setDefaultTimeout(20000);
 await ctx.route('**/*',route=>{const request=route.request(),u=new URL(request.url()),kind=request.resourceType(),method=request.method();if(!['GET','HEAD'].includes(method)){report.blocked.push({width,entry,method,host:u.hostname,path:u.pathname,kind,reason:'all mutations blocked'});return route.abort();}const own=u.origin===new URL(base).origin,publicHost=u.hostname==='pposiechnice.pl',staticAsset=assets.has(u.hostname)&&['stylesheet','font','image','script'].includes(kind);if(!own&&!publicHost&&!staticAsset){report.blocked.push({width,entry,method,host:u.hostname,path:u.pathname,kind,reason:'unrelated host blocked'});return route.abort();}if(kind==='document'&&publicHost){assert.equal(u.searchParams.get('page_id'),'981');assert.equal(u.searchParams.get('lang'),'en');report.navigation.push({width,entry,method,url:u.href,referrer:request.headers().referer||null});}return route.continue();});
 await ctx.addInitScript(()=>{if(location.hostname!=='127.0.0.1')return;const data=Object.fromEntries(['firstName','lastName','phone','messenger','citizenship','gender','age','location','stayDuration','physicalWork','physicalDetails','performanceMetrics','fastPace','watchedVideos','understandsRole','longHours'].map(k=>[k,'']));Object.assign(data,{firstName:'QA',lastName:'FIXTURE',phone:'+99912345678',messenger:'telegram',citizenship:'FIXTURE',gender:'undisclosed',age:'30',location:'any',stayDuration:'six',physicalWork:'no',performanceMetrics:'no',fastPace:'no',watchedVideos:'no',understandsRole:'no',longHours:'no',consent:false});localStorage.setItem('citronex_screening_application_v17',JSON.stringify({version:'17.0.0',id:'KAND-PRIVACY-FIXTURE',routeKey:'||||',language:'en',recruiterId:'yana',step:3,data,savedAt:Date.now()}));});
 const page=await ctx.newPage();let popup;
 try{
  await page.goto(base+'apply/');await page.locator('[data-action="resume"]').click();await page.locator('#consent').waitFor();const before=await page.evaluate(()=>localStorage.getItem('citronex_screening_application_v17'));assert(!await page.locator('#consent').isChecked());const link=entry==='consent'?page.locator('.consent-box a'):page.locator('#footerPrivacy');assert.equal(await link.getAttribute('href'),privacy);assert.equal(await link.getAttribute('target'),'_blank');assert.equal(await link.getAttribute('rel'),'noopener noreferrer');await page.locator(entry==='consent'?'#consent':'#footerPdf').focus();await page.keyboard.press('Tab');assert(await link.evaluate(n=>n===document.activeElement));[popup]=await Promise.all([page.waitForEvent('popup'),page.keyboard.press('Enter')]);await popup.waitForLoadState('domcontentloaded',{timeout:60000});await popup.locator('.page__content').waitFor({timeout:60000});await popup.locator('.page__content p').first().waitFor();await popup.evaluate(()=>document.fonts.ready);const u=new URL(popup.url());assert.equal(u.hostname,'pposiechnice.pl');assert.equal(u.searchParams.get('page_id'),'981');assert.equal(u.searchParams.get('lang'),'en');assert.equal(await popup.evaluate(()=>window.opener===null),true);assert.equal(await popup.evaluate(()=>document.referrer),'');
  const text=await popup.locator('.page__content').innerText();assert(text.includes('Information obligation under article 13'));assert(text.includes('Przedsiębiorstwo Produkcji Ogrodniczej'));assert(text.includes('Opolska 30'));assert(text.includes('The data is not subject to automatic profiling.'));await popup.screenshot({path:join(reportDir,`privacy-${width}-${entry}-viewport.png`)});const paragraphs=popup.locator('.page__content p'),count=await paragraphs.count(),dom=[];
  for(let i=0;i<count;i++){
   const n=paragraphs.nth(i),t=(await n.innerText()).trim();if(!t)continue;await n.evaluate(n=>n.scrollIntoView({block:'center',behavior:'instant'}));await popup.waitForTimeout(100);const fit=await n.evaluate(n=>{const f=n.getBoundingClientRect(),range=document.createRange();range.selectNodeContents(n);return {painted:n.checkVisibility({checkOpacity:true,checkVisibilityCSS:true}),rect:{x:f.x,y:f.y,width:f.width,height:f.height},fit:n.scrollWidth<=n.clientWidth+1&&f.left>=0&&f.right<=innerWidth+1&&[...range.getClientRects()].every(r=>r.left>=f.left-1&&r.right<=f.right+1),pageFits:document.documentElement.scrollWidth<=innerWidth+1};});const file=`privacy-${width}-${entry}-paragraph-${String(i).padStart(2,'0')}.png`;await n.screenshot({path:join(reportDir,file)});report.captures.push({width,entry,file,index:i,text:t,...fit});dom.push({index:i,text:t,...fit});
  }
  assert(dom.length>=12);await popup.close();popup=null;await page.bringToFront();assert.equal(await page.evaluate(()=>localStorage.getItem('citronex_screening_application_v17')),before);assert(!await page.locator('#consent').isChecked());assert.equal(await page.locator('.progress-meta strong').innerText(),'3 / 3');assert(await page.locator('[data-action="next"]').isVisible());report.rows.push({width,entry,status:'passed',originalURL:privacy,finalURL:u.href,nativeTabEnter:true,noReferrer:true,noOpener:true,livePublicText:text,paragraphs:dom,returnedToOriginalFixture:true,answersAndDraftUnchanged:true,consentNotGiven:true,applicationDeliveryAttempts:0});
 }catch(e){await page.screenshot({path:join(reportDir,`failure-application-${width}-${entry}.png`)}).catch(()=>{});await popup?.screenshot({path:join(reportDir,`failure-public-${width}-${entry}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
try{await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();for(const width of [320,1280])for(const entry of ['consent','footer'])await run(width,entry);assert.equal(report.rows.length,4);assert.equal(report.navigation.length,4);assert(report.navigation.every(x=>x.referrer===null));report.allPolicyParagraphsFit=report.captures.every(x=>x.painted&&x.fit&&x.pageFits);report.status='PASSED_4_NATIVE_PRIVACY_LINK_LIVE_DESTINATION_AND_RETURN_FLOWS';}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();report.finished=new Date().toISOString();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
